from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def read(p): return (ROOT/p).read_text(encoding="utf-8")
def write(p,s): (ROOT/p).write_text(s,encoding="utf-8")

# Bound action assessment latency, fail fast during provider backpressure, and open a short degraded circuit.
p=Path("src/ai-client.js"); s=read(p)
start=s.index("async function directActionAssessment(")
end=s.index("\nexport function startTurnAIJobs",start)
new='''const ACTION_ASSESSMENT_CIRCUIT_FAILURES=2;\nconst ACTION_ASSESSMENT_CIRCUIT_OPEN_MS=60000;\nconst actionAssessmentCircuit={worldId:"",failures:0,openUntil:0,lastError:""};\nexport function actionAssessmentRuntimeSnapshot(){return {...actionAssessmentCircuit}}\nfunction resetActionAssessmentCircuit(worldId=actionAssessmentCircuit.worldId){actionAssessmentCircuit.worldId=String(worldId||"");actionAssessmentCircuit.failures=0;actionAssessmentCircuit.openUntil=0;actionAssessmentCircuit.lastError=""}\nfunction noteActionAssessmentFailure(worldId,error){if(actionAssessmentCircuit.worldId!==String(worldId||""))resetActionAssessmentCircuit(worldId);actionAssessmentCircuit.failures+=1;actionAssessmentCircuit.lastError=String(error?.message||error||"").slice(0,500);if(actionAssessmentCircuit.failures>=ACTION_ASSESSMENT_CIRCUIT_FAILURES)actionAssessmentCircuit.openUntil=Date.now()+ACTION_ASSESSMENT_CIRCUIT_OPEN_MS}\nasync function directActionAssessment(payload,label,compact=false){\n const raw=await directChat({aiTask:"action",disableOptimization:compact,retryOnTimeout:false,timeoutMs:compact?10000:18000,maxOutputTokens:compact?700:650,temperature:0,system:compact?SHARED_ACTION_ASSESS_SYSTEM+" 不要解釋，只回 JSON。":SHARED_ACTION_ASSESS_SYSTEM,user:JSON.stringify(payload)});\n return {...normalizeActionAssessment(parseJSON(raw),label,payload?.snapshot||{}),source:compact?"AI_RETRY":"AI"}\n}\nexport async function assessPlayerAction(state,action){\n const label=String(action||"").trim().slice(0,180);if(!label)throw new Error("ACTION_REQUIRED");\n const fast=fastLocalActionAssessment(state,label);if(fast)return fast;\n const snapshot=actionFeasibilitySnapshot(state),payload={action:label,snapshot},worldId=String(state?.world?.id||"");\n if(actionAssessmentCircuit.worldId!==worldId)resetActionAssessmentCircuit(worldId);\n if(!hasDirectAI()){try{const server=await post("/api/action",{action:label,snapshot});return {...normalizeActionAssessment(server.assessment,label,snapshot),source:"SERVER_AI"}}catch(e){return degradedActionAssessment(state,label,e)}}\n if(actionAssessmentCircuit.openUntil>Date.now())return degradedActionAssessment(state,label,new Error(`ACTION_ASSESSMENT_CIRCUIT_OPEN: ${actionAssessmentCircuit.lastError||"provider degraded"}`));\n if(actionAssessmentCircuit.openUntil)resetActionAssessmentCircuit(worldId);\n try{const value=await directActionAssessment(payload,label,false);resetActionAssessmentCircuit(worldId);return value}\n catch(firstError){\n  if(/AI_RATE_LIMIT_BACKPRESSURE|AI_HTTP_429/.test(String(firstError?.message||firstError))){noteActionAssessmentFailure(worldId,firstError);return degradedActionAssessment(state,label,firstError)}\n  try{const value=await directActionAssessment({action:label,snapshot},label,true);resetActionAssessmentCircuit(worldId);return value}\n  catch(secondError){const e=new Error((firstError?.message||String(firstError))+" | RETRY: "+(secondError?.message||String(secondError)));noteActionAssessmentFailure(worldId,e);return degradedActionAssessment(state,label,e)}\n }\n}\n'''
s=s[:start]+new+s[end:]
write(p,s)

# Do not let player-critical tasks sit through long rate-limit backpressure windows.
p=Path("src/ai-settings.js"); s=read(p)
needle='const SHED_ON_RATE_LIMIT=new Set(["turn_deferred","runtime_expansion","history_deepening","runtime_quality","quality","quality_repair","runtime_repair"]);'
if needle not in s: raise SystemExit("SHED_ON_RATE_LIMIT not found")
s=s.replace(needle,needle+'\nconst PLAYER_CRITICAL_BACKPRESSURE_MAX_MS=6000;\nconst PLAYER_CRITICAL_TASKS=new Set(["action","scene","turn_state_fast","turn_state_deep"]);',1)
old='const runtime=directAIRuntimeControl(),spacing=Math.max(Number(row.spacingMs)||0,Number(runtime.requestSpacingMs)||0),startAt=Math.max(now,Number(row.until)||0,Number(row.nextRequestAt)||0),remaining=Math.max(0,startAt-now);if(spacing>0)row.nextRequestAt=startAt+spacing;if(!remaining)return;recordDebug("AI_BACKPRESSURE_WAIT",{provider,task,until:row.until,startAt,remainingMs:remaining,spacingMs:spacing,reason:cooldownRemaining?"RATE_LIMIT":"PACING"});await waitWithSignals(remaining,parentSignals)'
new='const runtime=directAIRuntimeControl(),spacing=Math.max(Number(row.spacingMs)||0,Number(runtime.requestSpacingMs)||0),startAt=Math.max(now,Number(row.until)||0,Number(row.nextRequestAt)||0),remaining=Math.max(0,startAt-now);if(PLAYER_CRITICAL_TASKS.has(taskName)&&remaining>PLAYER_CRITICAL_BACKPRESSURE_MAX_MS){recordDebug("AI_PLAYER_CRITICAL_BACKPRESSURE_BYPASS",{provider,task,remainingMs:remaining,limitMs:PLAYER_CRITICAL_BACKPRESSURE_MAX_MS,until:row.until});throw backpressureError(provider,task,row.until)}if(spacing>0)row.nextRequestAt=startAt+spacing;if(!remaining)return;recordDebug("AI_BACKPRESSURE_WAIT",{provider,task,until:row.until,startAt,remainingMs:remaining,spacingMs:spacing,reason:cooldownRemaining?"RATE_LIMIT":"PACING"});await waitWithSignals(remaining,parentSignals)'
if old not in s: raise SystemExit("honorRateLimit body not found")
s=s.replace(old,new,1)
write(p,s)

# Rotate grounded deterministic AutoTest recovery actions instead of repeating one hard-coded sentence.
p=Path("src/ai-autotest.js"); s=read(p)
start=s.index("export function deterministicAutotestDecision(")
end=s.index("export function normalizeAutotestDecision",start)
new='''function deterministicRecoveryCandidates(snapshot={},recentActions=[]){\n const recent=normalizedRecent(recentActions),loc=text(snapshot?.world?.location||"目前位置",100)||"目前位置",out=[];\n out.push(\n  {action:`檢查${loc}附近與剛才不同的地面、牆面或出口，確認是否有新的可驗證痕跡`,kind:"OBSERVE",targetId:null,progression:true},\n  {action:`搜尋${loc}另一側可安全接近的區域，確認是否出現新人物、物件或通道`,kind:"OBSERVE",targetId:null,progression:true},\n  {action:`觀察${loc}目前最明顯的人流、聲音或環境變化，選一項此前未追查的線索`,kind:"OBSERVE",targetId:null,progression:true},\n  {action:`檢查${loc}可見出口與附近物件的位置關係，選一條與剛才不同的方向再確認`,kind:"OBSERVE",targetId:null,progression:true}\n );\n return {all:out,fresh:out.filter(x=>!recent.has(text(x.action,180).toLowerCase()))}\n}\nexport function deterministicAutotestDecision(snapshot={},recentActions=[],reason="AI fallback"){\n const combat=snapshot?.combat?.active===true,suggestions=list(snapshot?.suggestions),recent=normalizedRecent(recentActions),stall=consecutiveAutotestStall(recentActions),last=list(recentActions).filter(x=>x&&typeof x==="object").at(-1)||{},lastKind=String(last.kind||"").toUpperCase(),lastTarget=String(last.targetId||"");\n if(combat)return {mode:"combat",combatAction:"attack",action:"attack",suggestionIndex:null,reason,goalReached:false,goalEvidence:"",fallback:true};\n const scored=suggestions.map((x,i)=>{const kind=String(x?.kind||"").toUpperCase(),targetId=String(x?.targetId||""),fresh=!recent.has(text(x?.action||x?.label,180).toLowerCase()),sameKind=Boolean(kind&&kind===lastKind),sameTarget=Boolean(lastTarget&&targetId&&targetId===lastTarget);let score=0;if(fresh)score+=30;if(x?.progression===true)score+=28;if(!["OBSERVE","GENERAL"].includes(kind))score+=stall>=2?20:5;if(stall>=3&&kind&&kind!==lastKind)score+=24;if(stall>=3&&lastTarget&&targetId&&targetId!==lastTarget)score+=24;if(stall>=3&&sameTarget)score-=45;if(stall>=5&&sameKind)score-=35;if(stall>=5&&kind==="TRAVEL")score+=40;if(stall>=5&&["RISKY","SOCIAL"].includes(kind)&&kind!==lastKind)score+=10;if(["HIGH","EXTREME"].includes(String(x?.risk||"").toUpperCase()))score-=stall<5?10:0;return {x,i,score,kind,targetId,sameKind,sameTarget,fresh}}).sort((a,b)=>b.score-a.score||a.i-b.i);\n let chosen=scored[0]||null;if(stall>=3){const diverse=scored.find(row=>row.fresh&&!row.sameKind&&(!lastTarget||!row.targetId||row.targetId!==lastTarget));chosen=diverse||scored.find(row=>row.fresh)||null}\n if(chosen?.x&&chosen.fresh)return {mode:"suggestion",suggestionIndex:chosen.i,action:text(chosen.x.action||chosen.x.label,180),kind:text(chosen.x.kind||"",30),progression:chosen.x.progression===true,targetId:chosen.x.targetId||null,combatAction:null,reason:`${reason}; deterministic recovery stall=${stall}`,goalReached:false,goalEvidence:"",fallback:true};\n const recovery=deterministicRecoveryCandidates(snapshot,recentActions),pool=recovery.fresh.length?recovery.fresh:recovery.all,index=pool.length?Math.abs((stall+list(recentActions).length)%pool.length):0,candidate=pool[index]||{action:"檢查目前位置附近最新出現的可見變化",kind:"OBSERVE",targetId:null,progression:true};\n return {mode:"free",suggestionIndex:null,action:text(candidate.action,180),kind:candidate.kind,progression:candidate.progression===true,targetId:candidate.targetId||null,combatAction:null,reason:`${reason}; deterministic grounded recovery stall=${stall}`,goalReached:false,goalEvidence:"",fallback:true}\n}\n'''
s=s[:start]+new+s[end:]
write(p,s)

# Make aggregate telemetry carry an inspectable error distribution.
p=Path("src/debug-telemetry.js"); s=read(p)
marker='export function telemetrySummary(entries=telemetryEntries()){\n'
idx=s.index(marker)
helper='''function telemetryErrorClass(entry){const raw=String(entry?.data?.error||entry?.data?.reason||entry?.data?.message||"");if(/AI_TIMEOUT/.test(raw))return "TIMEOUT";if(/AI_RATE_LIMIT|AI_HTTP_429/.test(raw))return "RATE_LIMIT";if(/Failed to fetch|fetch failed|NetworkError|ERR_NETWORK|ECONNRESET|ECONNREFUSED|ENOTFOUND|connection (?:reset|closed|refused)/i.test(raw))return "TRANSPORT";if(/EMPTY_AI_RESPONSE/.test(raw))return "EMPTY_RESPONSE";if(/INVALID_MODEL_JSON/.test(raw))return "INVALID_JSON";if(/AI_HTTP_5\\d\\d/.test(raw))return "HTTP_5XX";if(/AI_ABORTED/.test(raw)||entry?.data?.aborted===true)return "ABORTED";return "OTHER"}\nfunction countBy(rows,key){const out={};for(const row of rows){const value=String(key(row)||"unknown");out[value]=(out[value]||0)+1}return out}\n'''
if 'function telemetryErrorClass(' not in s: s=s[:idx]+helper+s[idx:]
old=' const latency=ok.reduce((a,x)=>a+(Number(x.data?.latencyMs)||0),0);\n return {sessionId:SESSION_ID,sessionStartedAt:SESSION_STARTED,exportedAt:Date.now(),entryCount:entries.length,gameplayEvents:gameplay.length,aiRequests:ai.length,aiSuccess:ok.length,aiUsageResponses:billable.length,errorCount:errors.length,preemptionCount:preemptions.length,tokenTotals:tokens,aiLatencyMsTotal:latency,aiLatencyMsAverage:ok.length?Math.round(latency/ok.length):0}\n}'
new=' const latency=ok.reduce((a,x)=>a+(Number(x.data?.latencyMs)||0),0),errorBreakdown={byType:countBy(errors,x=>x.type),byTask:countBy(errors,x=>x.data?.task||"non-ai"),byProvider:countBy(errors,x=>x.data?.provider||"unknown"),byClass:countBy(errors,telemetryErrorClass)};\n return {sessionId:SESSION_ID,sessionStartedAt:SESSION_STARTED,exportedAt:Date.now(),entryCount:entries.length,gameplayEvents:gameplay.length,aiRequests:ai.length,aiSuccess:ok.length,aiUsageResponses:billable.length,errorCount:errors.length,errorBreakdown,preemptionCount:preemptions.length,tokenTotals:tokens,aiLatencyMsTotal:latency,aiLatencyMsAverage:ok.length?Math.round(latency/ok.length):0}\n}'
if old not in s: raise SystemExit("telemetry summary tail not found")
